package ledger

// Refactor log:
//
//  1. Replaced the hand-rolled bubble sort (with its cryptic m1/m2 bit tricks)
//     with sort.Slice over a copy of the entries, ordered by date, then
//     description, then change. The input slice is still never mutated.
//  2. Replaced the one-goroutine-per-entry channel fan-out with a plain
//     sequential loop; the goroutines bought nothing (the work is trivial) and
//     made the code hard to follow.
//  3. Moved currency and locale validation to the top of FormatLedger. The old
//     code validated the locale only when building the header and the currency
//     only inside the worker goroutines, and needed a recursive call for the
//     empty-ledger case just to trigger that validation.
//  4. Extracted date validation/formatting into formatDate.
//  5. Extracted the two nearly identical amount-formatting branches into a
//     single formatAmount driven by a per-locale table.
//  6. Replaced the rune-counting loop with utf8.RuneCountInString.

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

const (
	dateColumnWidth    = 10
	descriptionWidth   = 25
	changeColumnWidth  = 13
	truncationSuffix   = "..."
)

var currencySymbols = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// localeInfo captures everything that differs between the supported locales.
type localeInfo struct {
	dateHeader, descHeader, changeHeader string
	groupSep, decimalSep                 string
}

var locales = map[string]localeInfo{
	"en-US": {"Date", "Description", "Change", ",", "."},
	"nl-NL": {"Datum", "Omschrijving", "Verandering", ".", ","},
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, ok := currencySymbols[currency]
	if !ok {
		return "", errors.New("invalid currency")
	}
	loc, ok := locales[locale]
	if !ok {
		return "", errors.New("invalid locale")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(loc))
	for _, entry := range sorted {
		date, err := formatDate(locale, entry.Date)
		if err != nil {
			return "", err
		}
		b.WriteString(date + " | " +
			padDescription(entry.Description) + " | " +
			rightPad(formatAmount(locale, symbol, entry.Change), changeColumnWidth) + "\n")
	}
	return b.String(), nil
}

func header(loc localeInfo) string {
	return pad(loc.dateHeader, dateColumnWidth) + " | " +
		pad(loc.descHeader, descriptionWidth) + " | " + loc.changeHeader + "\n"
}

// formatDate validates a "YYYY-MM-DD" date and renders it in the locale's
// style ("MM/DD/YYYY" for en-US, "DD-MM-YYYY" for nl-NL).
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// padDescription truncates overlong descriptions with an ellipsis and pads the
// rest to the fixed description column width.
func padDescription(description string) string {
	if len(description) > descriptionWidth {
		return description[:descriptionWidth-len(truncationSuffix)] + truncationSuffix
	}
	return pad(description, descriptionWidth)
}

// formatAmount renders a change in cents, e.g. "($1,234.56)" for a negative
// en-US amount or "$ 1.234,56-" for a negative nl-NL amount. Positive amounts
// get a trailing space so both styles are the same width.
func formatAmount(locale, symbol string, change int) string {
	loc := locales[locale]
	negative := change < 0
	cents := change
	if negative {
		cents = -cents
	}
	units := groupDigits(strconv.Itoa(cents/100), loc.groupSep)
	fraction := fmt.Sprintf("%02d", cents%100)
	number := units + loc.decimalSep + fraction

	if locale == "nl-NL" {
		sign := " "
		if negative {
			sign = "-"
		}
		return symbol + " " + number + sign
	}
	if negative {
		return "(" + symbol + number + ")"
	}
	return symbol + number + " "
}

// groupDigits inserts the locale's thousands separator into a non-negative
// integer, e.g. "1234567" -> "1,234,567".
func groupDigits(digits, sep string) string {
	var b strings.Builder
	for i, r := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteRune(r)
	}
	return b.String()
}

func pad(s string, width int) string {
	return s + strings.Repeat(" ", width-len(s))
}

func rightPad(s string, width int) string {
	return strings.Repeat(" ", width-utf8.RuneCountInString(s)) + s
}

